 // Helper functions

+// claudeStopReasonToOpenAI maps a Claude stop_reason to an OpenAI finish_reason.
+func claudeStopReasonToOpenAI(stopReason string) string {
+	switch stopReason {
+	case "tool_use":
+		return "tool_calls"
+	case "max_tokens":
+		return "length"
+	default:
+		return "stop"
+	}
+}
